+
+    fn download_to_file(
+        &self,
+        path: &Path,
+        resume_info: Option<ResumeInfo>,
+    ) -> Result<(), DownloadError> {
+        let (resume_from, etag) = resume_info
+            .as_ref()
+            .map(|r| (Some(r.downloaded), r.etag.as_deref()))
+            .unwrap_or((None, None));
