+            }
+
+            if let Some(ref cb) = self.on_progress {
+                cb(Progress::Chunk {
+                    current: downloaded,
+                    total,
+                });
+            }
+        }
+
+        if let Some(ref cb) = self.on_progress {
+            cb(Progress::Complete {
+                total,
+            });
+        }
