+    fn download_layers_sequential(
+        &self,
+        layers: &[&OciLayer],
+        output_dir: &Path,
+    ) -> Result<Vec<PathBuf>, DownloadError> {
+        let mut paths = Vec::new();
+        let mut downloaded = 0u64;
