+    pub fn fetch_manifest(&self) -> Result<OciManifest, DownloadError> {
+        let url = format!(
+            "{}/{}/manifests/{}",
+            self.api.trim_end_matches('/'),
+            self.reference.package,
+            self.reference.tag
