+    pub fn download_blob(&self) -> Result<Vec<PathBuf>, DownloadError> {
+        let filename = self
+            .reference
+            .package
+            .rsplit_once('/')
+            .map(|(_, name)| name)
+            .unwrap_or(&self.reference.tag);
