_⚠️ Potential issue_ | _🔴 Critical_

**Resume metadata is never applied**

Because we bail out as soon as `output_path.is_file()` is true, we either return early or delete the partial file before ever calling `read_resume`. That means an interrupted download (file + xattr present) always restarts from byte 0, so the advertised resume support is effectively dead. Please load the resume info before evaluating overwrite mode, keep it when we intend to continue, and only drop both file and xattr when the chosen overwrite option really forces a fresh download. 
```diff
-        let resume_info = if output_path.is_file() {
-            match self.overwrite {
-                OverwriteMode::Skip => return Ok(output_path),
-                OverwriteMode::Force => {
-                    fs::remove_file(&output_path)?;
-                    None
-                }
-                OverwriteMode::Prompt => {
-                    if !prompt_overwrite(&output_path)? {
-                        return Ok(output_path);
-                    }
-                    fs::remove_file(&output_path)?;
-                    None
-                }
-            }
-        } else {
-            read_resume(&output_path)
-        };
+        let mut resume_info = read_resume(&output_path);
+        if output_path.is_file() {
+            match self.overwrite {
+                OverwriteMode::Skip => return Ok(output_path),
+                OverwriteMode::Force => {
+                    fs::remove_file(&output_path)?;
+                    resume_info = None;
+                }
+                OverwriteMode::Prompt => {
+                    if resume_info.is_none() && !prompt_overwrite(&output_path)? {
+                        return Ok(output_path);
+                    }
+                    fs::remove_file(&output_path)?;
+                    resume_info = None;
+                }
+            }
+        }
```


