+pub async fn use_alternate_package(name: &str) -> SoarResult<()> {
+    let state = AppState::new();
+    let diesel_db = state.diesel_core_db()?;
+
+    let packages = diesel_db.with_conn(|conn| {
+        CoreRepository::list_filtered(
+            conn,
+            None,
+            Some(name),
+            None,
+            None,
+            None,
+            None,
+            None,
+            Some(SortDirection::Asc),
+        )
+    })?;
