 ) -> Result<usize, Box<dyn Error + Send + Sync + 'static>> {
+    conn.transaction(|conn| {
         // Check for text type OR blob containing text JSON (starts with '[' or '{')
         // Use hex comparison for blobs: 5B = '[', 7B = '{'
