+        let nests = NestRepository::list_all(nests_db.conn())
+            .map_err(|e| SoarError::Custom(format!("listing nests: {}", e)))?;
+
+        let nests_repo_path = self.config().get_repositories_path()?.join("nests");
+
+        let mut tasks = Vec::new();
+
+        for nest in nests {
