+            let registry_nest = soar_registry::Nest {
+                id: nest.id as i64,
+                name: nest.name.clone(),
+                url: nest.url.clone(),
+            };
+            let task = tokio::task::spawn(async move {
+                fetch_nest_metadata(&registry_nest, force, etag).await
+            });
+            tasks.push((task, nest));
