+                })?;
+
+                if let Some(new_pkg_id) = replacement {
+                    info!(
+                        "[{}] {} is replaced by {} in {}",
+                        Colored(Blue, "Note"),
+                        Colored(Red, &pkg.pkg_id),
+                        Colored(Green, &new_pkg_id),
+                        Colored(Magenta, &repo_name)
