+
+                    diesel_core_db.with_conn(|conn| {
+                        CoreRepository::update_pkg_id(conn, &repo_name, &pkg.pkg_id, &new_pkg_id)
+                    })?;
+                }
+            }
+        }
+
+        metadata_db
+            .with_conn(|conn| MetadataRepository::update_repo_metadata(conn, &repo.name, etag))?;
