+                    for nest in nests {
+                        let nest_path = nests_repo_path.join(&nest.name);
+                        let metadata_db = nest_path.join("metadata.db");
+                        if metadata_db.is_file() {
+                            let nest_name = format!("nest-{}", nest.name);
+                            manager.add_repo(&nest_name, metadata_db)?;
