+        Ok(manager)
+    }
+
+    #[inline]
+    pub fn config(&self) -> &Config {
+        &self.inner.config
+    }
+
+    /// Reads the etag from an existing metadata database.
+    fn read_repo_etag(&self, repo: &Repository) -> Option<String> {
+        let repo_path = repo.get_path().ok()?;
+        let metadata_db = repo_path.join("metadata.db");
