+    if assets.is_empty() {
+        return Err(SoarError::Custom("No assets found in release".into()));
+    }
+
+    assets
+        .iter()
+        .find(|a| fast_glob::glob_match(pattern, a.name()))
+        .ok_or_else(|| {
+            let available = assets
+                .iter()
+                .map(|a| a.name())
+                .collect::<Vec<_>>()
+                .join(", ");
