-                    );
-                }
+        let installed_names: std::collections::HashSet<&str> =
+            report.installed.iter().map(|i| i.pkg_name.as_str()).collect();
+        for (pkg_name, version) in &version_updates {
+            if installed_names.contains(pkg_name.as_str()) {
+                if let Err(e) =
