+    let existing_install = installed_pkg
+        .cloned()
+        .or_else(|| installed_packages.into_iter().next());
+
+    Ok(ResolveResult::Resolved(vec![InstallTarget {
+        package: url_pkg.to_package(),
+        existing_install,
