+                Ok((install_dir, symlinks)) => {
+                    if !install_dir.as_os_str().is_empty() {
+                        installed.lock().unwrap().push(InstalledInfo {
+                            pkg_name: target.package.pkg_name.clone(),
+                            pkg_id: target.package.pkg_id.clone(),
