+///
+/// Each update is essentially an install of the new version followed by
+/// cleanup of old versions (unless `keep_old` is true).
+pub async fn perform_update(
+    ctx: &SoarContext,
+    updates: Vec<UpdateInfo>,
+    keep_old: bool,
+) -> SoarResult<UpdateReport> {
