+            .collect()
+    } else {
+        metadata_mgr.query_all_flat(|repo_name, conn| {
+            let pkgs = MetadataRepository::list_all_minimal(conn)?;
+            Ok(pkgs
+                .into_iter()
+                .map(|pkg| {
+                    ListingWithRepo {
+                        repo_name: repo_name.to_string(),
+                        pkg,
+                    }
+                })
+                .collect())
+        })?
+    };
+
