use std::cmp::Ordering;

fn is_commit_hash(version: &str) -> bool {
    version.len() >= 7
        && version.len() <= 40
        && version.chars().all(|c: char| c.is_ascii_hexdigit())
        && version.chars().any(|c: char| c.is_ascii_alphabetic())
}

fn segments(version: &str) -> Segments {
    Segments { rest: version }
}

fn compare_segment(a: &str, b: &str) -> Ordering {
    match (a.parse::<u64>(), b.parse::<u64>()) {
        (Ok(x), Ok(y)) => x.cmp(&y),
        (Ok(_), Err(_)) => Ordering::Greater,
        (Err(_), Ok(_)) => Ordering::Less,
        (Err(_), Err(_)) => a.cmp(b),
    }
}

struct Segments<'a> {
    rest: &'a str,
}

impl<'a> Iterator for Segments<'a> {
    type Item = &'a str;

    fn next(&mut self) -> Option<Self::Item> {
        while let Some(c) = self.rest.chars().next() {
            if c.is_ascii_alphanumeric() {
                break;
            }
            self.rest = &self.rest[c.len_utf8()..];
        }
        if self.rest.is_empty() {
            return None;
        }
        let numeric = self.rest.starts_with(|c: char| c.is_ascii_digit());
        let end = self
            .rest
            .find(|c: char| c.is_ascii_digit() != numeric || !c.is_ascii_alphanumeric())
            .unwrap_or(self.rest.len());
        let (seg, tail) = self.rest.split_at(end);
        self.rest = tail;
        Some(seg)
    }
}

fn compare_versions(a: &str, b: &str) -> Ordering {
    if a != b && is_commit_hash(a) && is_commit_hash(b) {
        return Ordering::Equal;
    }
    let mut left = segments(a);
    let mut right = segments(b);
    loop {
        match (left.next(), right.next()) {
            (None, None) => return Ordering::Equal,
            (Some(x), None) => {
                if x.starts_with(|c: char| c.is_ascii_digit()) {
                    return Ordering::Greater;
                } else {
                    return Ordering::Less;
                }
            }
            (None, Some(y)) => {
